// Segundo intento (B): normalizar ANTES de comparar y emparejar por código limpio. Una línea por cambio real.
// Solo formato (decimales, espacios, mayúsculas) no es un cambio. Un retirado que reaparece con otro código se marca.
const limpio = (s) => String(s ?? '').replace(/\s+/g, ' ').trim();
const num = (s) => { const t = limpio(s); if (t === '') return null; const v = Number(t.replace(/\./g, '').replace(',', '.')); return Number.isFinite(v) ? v : null; };
const fila = (r) => ({ codigo: limpio(r.codigo), producto: limpio(r.producto), categoria: limpio(r.categoria), precio: num(r.precio), stock: num(r.stock), proveedor: limpio(r.proveedor) });
const enero = new Map($('Extraer tabla (enero)').all().map((it) => fila(it.json)).map((r) => [r.codigo, r]));
const febrero = new Map($('Extraer tabla (febrero)').all().map((it) => fila(it.json)).map((r) => [r.codigo, r]));
const out = [];
const igualTexto = (a, b) => a.toLowerCase() === b.toLowerCase();
for (const [k, a] of enero) {
  const b = febrero.get(k);
  if (!b) { out.push({ codigo: k, tipo: 'eliminado', campo: null, antes: a.producto, despues: null, aviso: '', estado: 'ok', _producto: a.producto }); continue; }
  if (a.producto !== b.producto) out.push({ codigo: k, tipo: 'cambiado', campo: 'producto', antes: a.producto, despues: b.producto, aviso: '', estado: 'ok' });
  if (!igualTexto(a.categoria, b.categoria)) out.push({ codigo: k, tipo: 'cambiado', campo: 'categoria', antes: a.categoria, despues: b.categoria, aviso: '', estado: 'ok' });
  if (!igualTexto(a.proveedor, b.proveedor)) out.push({ codigo: k, tipo: 'cambiado', campo: 'proveedor', antes: a.proveedor, despues: b.proveedor, aviso: '', estado: 'ok' });
  if (a.precio !== b.precio) out.push({ codigo: k, tipo: 'cambiado', campo: 'precio', antes: a.precio, despues: b.precio, aviso: '', estado: 'ok' });
  if (a.stock !== b.stock) out.push({ codigo: k, tipo: 'cambiado', campo: 'stock', antes: a.stock, despues: b.stock, aviso: '', estado: 'ok' });
}
for (const [k, b] of febrero) if (!enero.has(k)) out.push({ codigo: k, tipo: 'añadido', campo: null, antes: null, despues: b.producto, aviso: '', estado: 'ok', _producto: b.producto });
// Posible cambio de código: un retirado y un añadido con el mismo nombre de producto.
for (const e of out.filter((x) => x.tipo === 'eliminado')) for (const a of out.filter((x) => x.tipo === 'añadido')) if (e._producto === a._producto) { e.aviso = 'posible cambio de código: el mismo producto aparece como ' + a.codigo; e.estado = 'revisar'; a.aviso = 'posible cambio de código: el mismo producto estaba como ' + e.codigo; a.estado = 'revisar'; }
for (const x of out) delete x._producto;
const nT = (t) => out.filter((x) => x.tipo === t).length;
const resumen = { codigo: 'RESUMEN', tipo: '', campo: '', antes: null, despues: null, aviso: 'filas enero: ' + enero.size + ' · filas febrero: ' + febrero.size + ' · cambios reales: ' + out.length + ' (cambiados: ' + nT('cambiado') + ' · añadidos: ' + nT('añadido') + ' · eliminados: ' + nT('eliminado') + ') · a revisar: ' + out.filter((x) => x.estado === 'revisar').length, estado: '' };
return [...out.map((x) => ({ json: x })), { json: resumen }];
